RETIRADAS = [
    ("institucion_ver", "Ver instituciones"),
    ("institucion_administrar", "Administrar instituciones"),
]


def retirar(apps, schema_editor):
    Permission = apps.get_model("auth", "Permission")
    CapacidadRevocada = apps.get_model("users", "CapacidadRevocada")
    permisos = Permission.objects.filter(
        content_type__app_label="users",
        content_type__model="capacidad",
        codename__in=[c for c, _ in RETIRADAS],
    )
    for permiso in permisos:
        for grupo in permiso.group_set.all():
            CapacidadRevocada.objects.get_or_create(grupo=grupo, codename=permiso.codename, migracion=MIGRACION)
    permisos.delete()  # cascada sobre auth_group_permissions


def restituir(apps, schema_editor):
    ContentType = apps.get_model("contenttypes", "ContentType")
    Permission = apps.get_model("auth", "Permission")
    CapacidadRevocada = apps.get_model("users", "CapacidadRevocada")
    content_type, _ = ContentType.objects.get_or_create(app_label="users", model="capacidad")
    por_codename = {}
    for codename, nombre in RETIRADAS:
        por_codename[codename], _ = Permission.objects.get_or_create(
            content_type=content_type, codename=codename, defaults={"name": nombre}
        )
    filas = CapacidadRevocada.objects.filter(migracion=MIGRACION).select_related("grupo")
    for fila in filas:
        permiso = por_codename.get(fila.codename)
        if permiso is not None:
            fila.grupo.permissions.add(permiso)
    filas.delete()


